const MENU_BAR_CSS = `
/* NO backdrop-filter here, deliberately. The bar spans the tile's top corners,
   and a backdrop-filtered element is GPU-composited — inside this heavily
   animated scene Electron's compositor draws that layer WITHOUT applying the
   tile's rounded overflow clip, so the bar's own square corners poked out past
   the window's curve (the "gray 90° corner" on every action hero; the
   integration heroes have no menu bar, which is why they were fine). Plain
   paint always honors the rounded clip. At 22px tall the blur bought nothing;
   a near-opaque fill reads identically. */
.mbar {
  position: absolute; top: 0; left: 0; right: 0; height: 22px; z-index: 0;
  display: flex; align-items: center; gap: 9px; padding: 0 10px;
  background: rgba(246,247,250,0.96);
  border-bottom: 0.5px solid rgba(15,23,42,0.07);
  color: rgba(20,22,28,0.62);
  font-size: 8px; font-weight: 400; letter-spacing: 0.004em; line-height: 1;
}
.mbar-apple { width: 9px; height: 11px; fill: rgba(20,22,28,0.72); flex: none; }
.mbar-app { font-weight: 640; color: rgba(20,22,28,0.82); }
.mbar-menu { color: rgba(20,22,28,0.6); }
.mbar-right {
  margin-left: auto; display: flex; align-items: center; gap: 7px;
  color: rgba(20,22,28,0.55);
}
`;
